{
  "claims": [
    {
      "claim": "Elacridar and its close dimethoxy-TIQ/phenethyl-carboxamide analogs show very low brain penetration in direct human and rodent PET studies, with brain SUV values around 0.1-0.5 and consistent P-gp/BCRP efflux, indicating this chemotype does not achieve adequate CNS exposure without transporter blockade.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 3",
        "Molecule 11"
      ],
      "record_ids": [
        "Record 3-1",
        "Record 3-2",
        "Record 3-7",
        "Record 3-8",
        "Record 3-10",
        "Record 11-1",
        "Record 11-2"
      ]
    },
    {
      "claim": "A fluorine-substituted elacridar analogue with the same TIQ-phenethyl-carboxamide core also had poor baseline brain uptake in rodents, and brain uptake increased several-fold only after P-gp/BCRP inhibition, confirming efflux-limited CNS access.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 1"
      ],
      "record_ids": [
        "Record 1-1"
      ]
    },
    {
      "claim": "The very close query analog [18F]4 is an avid dual P-gp/BCRP substrate, with brain AUC 8-9-fold higher in P-gp/Bcrp knockout mice and about 7-fold higher after elacridar co-injection, showing that efflux transporters strongly restrict its brain exposure.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 16"
      ],
      "record_ids": [
        "Record 16-2",
        "Record 16-4",
        "Record 16-5",
        "Record 16-6"
      ]
    },
    {
      "claim": "Quantitative brain-exposure data for the elacridar scaffold in humans and mice are very low (K1 ~0.003 min-1 in human brain; brain level <0.002 µM in mice), well below levels considered meaningful for CNS drug exposure.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-2"
      ]
    },
    {
      "claim": "Some less structurally matched or less complete TIQ-based probes and one methyl-ester analog show high brain uptake in mice, but they lack the full amide/quinoline efflux-liable architecture of the query and do not outweigh the direct poor-penetration and efflux data for the immediate analog class.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 13",
        "Molecule 2",
        "Molecule 4",
        "Molecule 7",
        "Molecule 9"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 2-1",
        "Record 4-1",
        "Record 7-1",
        "Record 9-1"
      ]
    }
  ],
  "final_prediction": "fail"
}

